useEffect(() => {
  const timer = setInterval(() => console.log('tick'), 1000)
  return () => clearInterval(timer)  // 清理：卸载时停掉定时器
}, [])

function useOnline() {
  const [online, setOnline] = useState(navigator.onLine)
  useEffect(() => {
    const update = () => setOnline(navigator.onLine)
    window.addEventListener('online', update)
    window.addEventListener('offline', update)
    return () => { window.removeEventListener('online', update)
      window.removeEventListener('offline', update) }
  }, [])
  return online
}

const ThemeCtx = createContext('light')
function App() {
  return <ThemeCtx.Provider value='dark'><Toolbar /></ThemeCtx.Provider>
}
function Toolbar() {
  const theme = useContext(ThemeCtx)
  return <div>当前主题：{theme}</div>
}

const inputRef = useRef(null)
function focus() { inputRef.current.focus() }
return <><input ref={inputRef} /><button onClick={focus}>聚焦</button></>
